class Solution:
    def processEvents(self, events: List[str]) -> List[int]:
        score = counter = 0
        for e in events:
            if counter == 10:
                break
            if e == "W":
                counter += 1
            elif e == "WD" or e == "NB":
                score += 1
            else:
                score += int(e)
        return [score, counter]

